    for v in key:
        if not pattern or v != pattern[-1] or len(pattern) == 1:
            pattern.append(v)
        if len(pattern) == 2 and pattern[0] == pattern[1] and v == b:
            pattern.append(v)
            break
        if len(pattern) == 2 and pattern[0] != pattern[1]:
            break
    if len(pattern) == 1:
        pattern = [a, b]
    n = len(pattern)
    reverse_pattern = list(reversed(pattern))

    for r in range(min(3, h)):
        for c in range(w):
            if grid[r][c] in (a, b):
                g[r][c] = bg
    for r in range(h - 1):
        done = False
        for c in range(w - 1):
            if all(grid[r + dr][c + dc] == target_colour
                   for dr in range(2) for dc in range(2)):
                for dr in range(2):
                    for dc in range(2):
                        g[r + dr][c + dc] = bg
                done = True
                break
        if done:
            break

    def put(r, c, v):
        if 0 <= r < h and 0 <= c < w:
            g[r][c] = v

    def horizontal(r, c1, c2):
        step = 1 if c2 >= c1 else -1
        for c in range(c1, c2 + step, step):
            put(r, c, pattern[c % n])
        put(r, c2 + step, target_colour)
        return c2

    def vertical(c, r1, r2):
        step = 1 if r2 >= r1 else -1
        for r in range(r1, r2 + step, step):
            put(r, c, reverse_pattern[(r - c) % n])
        put(r2 + step, c, target_colour)
        return r2

    for sr in range(h):
        if grid[sr][0] != a or w < 2 or grid[sr][1] != other:
            continue

        # First arm: rightwards from the seed.
        x = 1
        while x + 1 < w and grid[sr][x + 1] == other:
            x += 1
        horizontal(sr, 0, x)

        # Second arm: follow the upright at its end.
        if sr > 0 and grid[sr - 1][x] == other:
            dr = -1
        elif sr + 1 < h and grid[sr + 1][x] == other:
            dr = 1
        else:
            continue
        y = sr + dr
        while 0 <= y + dr < h and grid[y + dr][x] == other:
            y += dr
        vertical(x, sr, y)

        # Third arm: turn along the corridor at the upright's far end.
        if x > 0 and grid[y][x - 1] == other:
            dc = -1
        elif x + 1 < w and grid[y][x + 1] == other:
            dc = 1
